{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/lab",
  "data": {
    "name": "CircularProgress",
    "displayName": "Circular Progress",
    "category": "Feedback & Status",
    "keywords": [
      "circular",
      "progress",
      "radial",
      "ring",
      "arc",
      "determinate",
      "indeterminate",
      "gauge",
      "meter",
      "donut"
    ],
    "props": [
      {
        "name": "value",
        "type": "number",
        "description": "Current value. Ignored when isIndeterminate is true.",
        "default": "0"
      },
      {
        "name": "max",
        "type": "number",
        "description": "Maximum value.",
        "default": "100"
      },
      {
        "name": "label",
        "type": "string",
        "description": "Accessible label for screen readers.",
        "required": true
      },
      {
        "name": "isLabelHidden",
        "type": "boolean",
        "description": "Visually hide the label (remains accessible). Defaults to true since circular progress typically shows center content instead.",
        "default": "true"
      },
      {
        "name": "hasValueLabel",
        "type": "boolean",
        "description": "Show the formatted value (e.g. \"75%\") in the center of the ring. Ignored when isIndeterminate is true or when children provide custom center content.",
        "default": "false"
      },
      {
        "name": "formatValueLabel",
        "type": "(value: number, max: number) => string",
        "description": "Custom value label formatter; defaults to a percentage string."
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Content displayed in the center of the ring: percentage, icon, or custom content. Takes precedence over hasValueLabel."
      },
      {
        "name": "size",
        "type": "'sm' | 'md' | 'lg'",
        "description": "Diameter of the progress ring (32px, 48px, 64px).",
        "default": "'md'"
      },
      {
        "name": "variant",
        "type": "'accent' | 'success' | 'warning' | 'error' | 'neutral'",
        "description": "Semantic color variant for the progress fill.",
        "default": "'accent'"
      },
      {
        "name": "isIndeterminate",
        "type": "boolean",
        "description": "Animated spinning indicator for unknown progress. Respects prefers-reduced-motion by slowing the animation.",
        "default": "false"
      },
      {
        "name": "isDisabled",
        "type": "boolean",
        "description": "Visually disabled: grays out the ring and text. Use for canceled or inactive operations.",
        "default": "false"
      },
      {
        "name": "xstyle",
        "type": "StyleXStyles",
        "description": "StyleX styles for layout customization (margins, positioning). Must be a stylex.create() value."
      }
    ],
    "theming": {
      "targets": [
        {
          "className": "astryx-circular-progress",
          "visualProps": [
            "variant",
            "size"
          ]
        },
        {
          "className": "astryx-circular-progress-track"
        },
        {
          "className": "astryx-circular-progress-fill",
          "visualProps": [
            "variant"
          ]
        }
      ]
    },
    "usage": {
      "description": "A circular progress indicator that shows completion as a ring or arc. Use it for upload progress, score displays, dashboard gauges, or compact progress where horizontal space is limited. Complements ProgressBar for radial layouts.",
      "bestPractices": [
        {
          "guidance": true,
          "description": "Pass a value for determinate progress; set isIndeterminate when the duration is unknown."
        },
        {
          "guidance": true,
          "description": "Show the value with hasValueLabel, or pass children for custom center content: an icon or short label."
        },
        {
          "guidance": true,
          "description": "Always provide a label, even though it is visually hidden by default; screen readers need it."
        },
        {
          "guidance": false,
          "description": "Use circular progress for long text labels; use ProgressBar instead, which has more room for label and value display."
        },
        {
          "guidance": false,
          "description": "Use an indeterminate CircularProgress for small inline loading states; Spinner is the inline indicator."
        }
      ]
    },
    "examples": [
      {
        "label": "Determinate with value label",
        "code": "<CircularProgress value={75} label=\"Upload progress\" hasValueLabel />"
      },
      {
        "label": "Indeterminate",
        "code": "<CircularProgress isIndeterminate label=\"Loading...\" />"
      },
      {
        "label": "Custom value format",
        "code": "<CircularProgress value={3.2} max={5} label=\"Disk usage\" hasValueLabel formatValueLabel={(v, m) => `${v} GB / ${m} GB`} />"
      },
      {
        "label": "Disabled",
        "code": "<CircularProgress value={30} label=\"Canceled\" isDisabled hasValueLabel />"
      }
    ],
    "package": "@astryxdesign/lab",
    "import": "@astryxdesign/lab",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
